"use client"

import { useEffect, useRef, useState } from "react"
import Image from "next/image"
import Link from "next/link"
import { cn } from "@/lib/utils"

const projectGroups = [
  {
    id: "residences",
    label: "Residences",
    projects: [
      {
        title: "Casa Monteverde",
        image: "/images/project-1.jpg",
      },
      {
        title: "Rainforest Pavilion",
        image: "/images/project-4.jpg",
      },
    ],
  },
  {
    id: "resorts",
    label: "Resorts",
    projects: [
      {
        title: "Nosara Wellness Retreat",
        image: "/images/project-2.jpg",
      },
    ],
  },
  {
    id: "conceptual",
    label: "Conceptual Design",
    projects: [
      {
        title: "Peninsula Yoga Shala",
        image: "/images/project-3.jpg",
      },
    ],
  },
] as const

export function Gallery() {
  const [isVisible, setIsVisible] = useState(false)
  const sectionRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
          observer.disconnect()
        }
      },
      { threshold: 0.1 }
    )

    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }

    return () => observer.disconnect()
  }, [])

  let projectIndex = 0

  return (
    <section
      ref={sectionRef}
      id="portfolio"
      className="scroll-mt-24 bg-background py-24 md:py-32 lg:scroll-mt-28"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        <div>
          <span
            className={cn(
              "text-xs tracking-widest text-muted-foreground uppercase opacity-0",
              isVisible && "animate-fade-in-up"
            )}
          >
            Our Work
          </span>
          <h2
            className={cn(
              "mt-4 font-serif text-4xl tracking-tight text-foreground opacity-0 md:text-5xl",
              isVisible && "animate-fade-in-up animation-delay-200"
            )}
          >
            <span className="text-balance">Featured Projects</span>
          </h2>
        </div>

        {projectGroups.map((group, gi) => (
          <div
            key={group.id}
            id={group.id}
            className={cn(
              "scroll-mt-24 lg:scroll-mt-28",
              gi === 0 ? "mt-12" : "mt-16"
            )}
          >
            <h3
              className={cn(
                "border-b border-border pb-3 font-serif text-2xl text-foreground opacity-0 md:text-3xl",
                isVisible && "animate-fade-in-up"
              )}
            >
              {group.label}
            </h3>
            <div className="mt-8 grid gap-6 md:grid-cols-2">
              {group.projects.map((project) => {
                const index = projectIndex++
                return (
                  <Link
                    key={project.title}
                    href={`#${group.id}`}
                    className={cn(
                      "group relative aspect-[4/3] overflow-hidden opacity-0",
                      isVisible && "animate-fade-in-up"
                    )}
                    style={{
                      animationDelay: isVisible ? `${(index + 2) * 100}ms` : "0ms",
                    }}
                  >
                    <Image
                      src={project.image}
                      alt={project.title}
                      fill
                      className="object-cover transition-transform duration-700 group-hover:scale-105"
                      sizes="(max-width: 768px) 100vw, 50vw"
                    />
                    <div className="absolute inset-0 bg-foreground/0 transition-colors duration-500 group-hover:bg-foreground/40" />
                    <div className="absolute inset-0 flex flex-col justify-end p-6 md:p-8">
                      <div className="translate-y-4 opacity-0 transition-all duration-500 group-hover:translate-y-0 group-hover:opacity-100">
                        <span className="text-xs tracking-widest text-primary-foreground/70 uppercase">
                          {group.label}
                        </span>
                        <h3 className="mt-1 font-serif text-2xl text-primary-foreground md:text-3xl">
                          {project.title}
                        </h3>
                      </div>
                    </div>
                  </Link>
                )
              })}
            </div>
          </div>
        ))}
      </div>
    </section>
  )
}
